import React, { useState, useEffect } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import Map from '../components/Map';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import { setEstimatedFare } from '../redux/slices/rideSlice';
import { toast } from 'react-toastify';

const RideBooking = () => {
  const { isAuthenticated } = useSelector((state) => state.auth);
  const { estimatedFare } = useSelector((state) => state.ride);
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const [formData, setFormData] = useState({
    pickupAddress: '',
    dropAddress: '',
    vehicleType: 'car',
    paymentMethod: 'wallet',
  });
  const [loading, setLoading] = useState(false);
  const [mapLocation, setMapLocation] = useState({ lat: 28.6139, lng: 77.2090 });

  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/login');
    }
  }, [isAuthenticated, navigate]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const calculateFare = async () => {
    if (!formData.pickupAddress || !formData.dropAddress) {
      toast.warning('Please enter both pickup and drop addresses');
      return;
    }

    try {
      const response = await api.post('/rides/calculate-fare', {
        pickupLocation: { coordinates: [mapLocation.lng, mapLocation.lat] },
        dropLocation: { coordinates: [mapLocation.lng + 0.1, mapLocation.lat + 0.1] },
        vehicleType: formData.vehicleType,
      });

      dispatch(setEstimatedFare(response.data.fare));
      toast.success('Fare calculated');
    } catch (error) {
      toast.error('Failed to calculate fare');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await api.post('/rides/book', {
        pickupLocation: { coordinates: [mapLocation.lng, mapLocation.lat] },
        dropLocation: { coordinates: [mapLocation.lng + 0.1, mapLocation.lat + 0.1] },
        pickupAddress: formData.pickupAddress,
        dropAddress: formData.dropAddress,
        vehicleType: formData.vehicleType,
        paymentMethod: formData.paymentMethod,
      });

      toast.success('Ride booked successfully!');
      navigate(`/ride/${response.data.ride._id}`);
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to book ride');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">
      <Header />

      <main className="flex-1 p-4 sm:p-6 lg:p-8">
        <div className="max-w-7xl mx-auto">
          <h1 className="text-3xl font-bold mb-8">Book a Ride</h1>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Booking Form */}
            <div className="lg:col-span-2">
              <form onSubmit={handleSubmit} className="bg-white rounded-lg shadow-md p-6 space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Pickup Address
                  </label>
                  <input
                    type="text"
                    name="pickupAddress"
                    value={formData.pickupAddress}
                    onChange={handleChange}
                    placeholder="Enter pickup location"
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-600"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Drop Address
                  </label>
                  <input
                    type="text"
                    name="dropAddress"
                    value={formData.dropAddress}
                    onChange={handleChange}
                    placeholder="Enter drop location"
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-600"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Vehicle Type
                  </label>
                  <select
                    name="vehicleType"
                    value={formData.vehicleType}
                    onChange={handleChange}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-600"
                  >
                    <option value="bike">Bike</option>
                    <option value="auto">Auto</option>
                    <option value="car">Car</option>
                    <option value="sedan">Sedan</option>
                    <option value="suv">SUV</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Payment Method
                  </label>
                  <select
                    name="paymentMethod"
                    value={formData.paymentMethod}
                    onChange={handleChange}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-600"
                  >
                    <option value="wallet">Wallet</option>
                    <option value="card">Card</option>
                    <option value="cash">Cash</option>
                    <option value="upi">UPI</option>
                  </select>
                </div>

                {estimatedFare && (
                  <div className="bg-blue-50 p-4 rounded-lg border border-blue-200">
                    <p className="text-gray-700">
                      Estimated Fare: <span className="font-bold text-lg">₹{estimatedFare.estimatedFare}</span>
                    </p>
                    <p className="text-sm text-gray-600">
                      Distance: {estimatedFare.distance} km
                    </p>
                  </div>
                )}

                <div className="flex gap-4">
                  <button
                    type="button"
                    onClick={calculateFare}
                    className="flex-1 bg-gray-600 text-white py-2 rounded-lg hover:bg-gray-700 font-bold transition"
                  >
                    Calculate Fare
                  </button>
                  <button
                    type="submit"
                    disabled={loading}
                    className="flex-1 bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 font-bold transition"
                  >
                    {loading ? 'Booking...' : 'Book Ride'}
                  </button>
                </div>
              </form>
            </div>

            {/* Map */}
            <div className="lg:col-span-1">
              <div className="bg-white rounded-lg shadow-md overflow-hidden">
                <Map latitude={mapLocation.lat} longitude={mapLocation.lng} />
              </div>
            </div>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  );
};

export default RideBooking;
